      {
        "fonte_id": "f_bbb437fd83",
        "localizador": "L06"
      }
    ],
    "lacunas": [],
    "motivo": "O aviso acrescenta uma única taxa de R$300,00, equivalente a 30.000 centavos.",
    "unidade": "BRL_centavo"
  },
  "justificativa": "O aviso mantém a disponibilidade do cartucho em D2 e confirma o procedimento padrão de montagem após aceite do laudo, sem alteração do término fixo da linha base em D10. Acrescenta somente a taxa de troca de R$300,00."
}

